function simRoleBar(){
 if(!presentation)return '';
 const roles=[['ronda','Vigia / Ronda','compass','Vigia'],['supervisor','Supervisão','eye','Superv.'],['gestor','Gestão','chart','Gestão'],['admin','Administração','settings','Admin']];
 const currentRole=user?.role??'ronda',point=session?.status==='active'?session.index+1:0,total=session?.route?.points.length??4;
 return `<div class="simulation-rolebar" aria-label="Ambiente interativo do aplicativo"><div class="simulation-caption"><span class="simulation-signal"></span><strong>Hondas Maxvel</strong><small>Dados locais de avaliação</small></div><nav class="simulation-roles" aria-label="Alternar perfis do aplicativo">${roles.map(([role,label,icon,short])=>`<button type="button" data-action="sim-role" data-role="${role}" aria-label="${label}" aria-pressed="${currentRole===role}" class="${currentRole===role?'selected':''}">${ic(icon)}<span class="role-long">${label}</span><span class="role-short" aria-hidden="true">${short}</span></button>`).join('')}</nav><div class="simulation-actions">${helpButton('profiles','perfil de acesso')}<span class="simulation-progress">${session?`Ponto ${Math.min(point,total)} / ${total}`:'Pronto para iniciar'}</span><button type="button" data-action="end-presentation" aria-label="Sair da simulação" title="Sair da simulação">${ic('close')}<span> Sair</span></button></div></div>`;
}
function beginSimulation(name,autoStart=false,startRole='ronda'){
 if(!presentation)priorSimulation={user:user?{...user}:null,view,session,mode};
 if(session?.status==='active'&&mode==='real'){notify('Finalize a ronda com GPS antes de explorar a simulação.');return;}
 stopLocation();toast.classList.remove('toast-visible');clearTimeout(toastTimer);presentation=true;screen='dashboard';mode='simulation';
 presentationName=(name||presentationName).slice(0,60);
 user={name:presentationName,role:startRole};
 view=startRole==='ronda'?'minha-ronda':'overview';
 session=autoStart?createSession(presentationName,DEMO_ROUTE,Date.now(),'simulation'):null;
 if(startRole==='ronda')selectedWatcherId=DEMO_WATCHERS.find(w=>w.name===presentationName)?.id??'v01';
 locationFix={...DEMO_ROUTE.base,accuracy:5,at:Date.now()};
 movement=null;
 if(session)save();
 render();window.scrollTo({top:0,behavior:'instant'});
 if(!tour.hasSeen())setTimeout(()=>tour.open(),350);
}
function endSimulation(){
 if(!presentation)return;
 stopLocation();movement=null;
 const prev=priorSimulation;
 presentation=false;priorSimulation=null;
 screen=prev?.user?'dashboard':'landing';user=prev?.user??null;
 view=prev?.view??'overview';session=prev?.session??null;mode=prev?.mode??'simulation';
 locationFix=null;render();window.scrollTo({top:0,behavior:'instant'});
}
function simulationIntro(){
 showDialog(`<div class="sim-onboarding"><img class="onboarding-lockup" src="./assets/horizon-maxvel-lockup.svg" alt="Hondas Maxvel · Tecnologia Horizon" width="300" height="62"><div class="eyebrow">AMBIENTE DE AVALIAÇÃO</div><h2>Experimente o aplicativo real</h2><p>Você usará as próprias telas do sistema, com o mapa e os registros funcionando em um cenário fictício.</p><div class="sim-intro-steps"><div>${ic('compass')}<span><strong>Execute a ronda</strong>Inicie, desloque-se e valide os pontos.</span></div><div>${ic('alert')}<span><strong>Teste uma saída da rota</strong>Justifique e veja o bloqueio da etapa.</span></div><div>${ic('eye')}<span><strong>Alterne para Supervisão</strong>Confira alertas, mapa e registros no mesmo aplicativo.</span></div></div><label class="field">Nome de exemplo<input id="presentation-name" maxlength="60" value="${esc(presentationName)}"></label><div class="sim-onboarding-actions">${btn('Entrar no aplicativo '+ic('arrow'),'launch-presentation','primary full')}${btn('Ler instruções detalhadas','guide','full')}</div><p class="map-caption">Sem GPS real e sem envio remoto. As regras de raio e permanência continuam valendo no cenário.</p></div>`);
}

